import{_t as e,it as t,n,rt as r}from"./chunks/framework.CzJE1L4g.js";var i=JSON.parse(`{"title":"介绍","description":"","frontmatter":{},"headers":[],"relativePath":"introduction.md","filePath":"introduction.md","lastUpdated":1792295848000}`),a={name:`introduction.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to “介绍”">​</a></h1><p>曦寒报表设计器（XiHan.ReportDesigner）是一款框架无关的报表设计器：以原生 Web Components 交付，可视化设计报表，在浏览器里按数据集与参数取数，算出明细表、分组报表、交叉表与看板并显示出来；看板上的卡片可以互相联动，表格的格子可以下钻，计算结果可以导出成 Excel 工作簿。属于曦寒懿（XiHanFun）开源生态，采用 MIT 授权。</p><h2 id="能做什么" tabindex="-1">能做什么 <a class="header-anchor" href="#能做什么" aria-label="Permalink to “能做什么”">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>用什么</th></tr></thead><tbody><tr><td>在业务页面里显示报表与看板</td><td><code>&lt;xh-report-viewer&gt;</code>：按报表定义取数、计算并绘出主体视图，带参数栏、联动与下钻事件</td></tr><tr><td>设计与修改报表</td><td><code>&lt;xh-report-designer&gt;</code>：数据面板、物料、字段栏、属性面板、问题列表、撤销重做与剪贴板，可切到预览态</td></tr><tr><td>导出</td><td>查看器的 <code>export(&#39;xlsx&#39;)</code> 把当前的计算结果写成工作簿；扩展可以登记别的格式</td></tr><tr><td>不显示界面，只做计算或校验</td><td><code>@xihan-report/core</code>：校验报表定义、生成取数请求、计算视图与卡片，浏览器与 Node.js 里都能用</td></tr></tbody></table><h2 id="设计原则" tabindex="-1">设计原则 <a class="header-anchor" href="#设计原则" aria-label="Permalink to “设计原则”">​</a></h2><ul><li><strong>框架无关</strong>：以原生 Web Components 交付，不绑定任何前端框架。元素用 Light DOM，样式只消费 <a href="https://ui.docs.xihanfun.com" target="_blank" rel="noreferrer">XiHan.UI</a> 的设计令牌，表格、图表与表单控件也都来自 XiHan.UI。</li><li><strong>零第三方依赖</strong>：运行时只依赖 <code>@xihan-report/*</code> 与 <code>@xihan-ui/*</code>，受限表达式、值格式化、聚合与 Excel 写出都来自 XiHan.UI。</li><li><strong>报表定义即数据</strong>：报表是纯 JSON，不含也不执行任何代码。计算字段与公式度量用受限表达式，导入报表定义不会带来脚本注入。</li><li><strong>数据由使用方掌控</strong>：组件不发网络请求。报表定义存在哪里、数据从哪里取、谁能改报表，都由使用方决定，经属性、回调与事件交给组件。</li><li><strong>没有全局状态</strong>：不往 <code>window</code> 上挂对象，不读写固定键名的本地存储，同一页面放多个实例互不影响；扩展也按实例传入，不做全局登记。</li></ul><h2 id="包与入口" tabindex="-1">包与入口 <a class="header-anchor" href="#包与入口" aria-label="Permalink to “包与入口”">​</a></h2><table tabindex="0"><thead><tr><th>入口</th><th>内容</th></tr></thead><tbody><tr><td><code>@xihan-report/core</code></td><td>报表定义的类型、校验、取数请求、计算、编辑操作与扩展的合并。纯 TypeScript，不依赖 DOM</td></tr><tr><td><code>@xihan-report/runtime</code></td><td>业务页面用的 <code>&lt;xh-report-viewer&gt;</code>，样式在 <code>@xihan-report/runtime/style.css</code></td></tr><tr><td><code>@xihan-report/runtime/locale</code></td><td>各语言的语言包，如 <code>reportZhCN</code>、<code>reportJaJP</code>，与 XiHan.UI 的内建语言包一一对应，查看器与设计器共用</td></tr><tr><td><code>@xihan-report/runtime/xlsx</code></td><td>把明细表、分组报表与交叉表的计算结果排成工作表，自己组织工作簿时用</td></tr><tr><td><code>@xihan-report/designer</code></td><td><code>&lt;xh-report-designer&gt;</code>，样式在 <code>@xihan-report/designer/style.css</code></td></tr></tbody></table><p>依赖方向固定为 <code>designer → runtime → core</code>。业务页面只需要 runtime，设计器只在需要编辑报表的地方加载；Excel 写出的代码在导出时才按需加载。</p><h2 id="工作流程" tabindex="-1">工作流程 <a class="header-anchor" href="#工作流程" aria-label="Permalink to “工作流程”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>设计器 &lt;xh-report-designer&gt;</span></span>
<span class="line"><span>  │  schema-change / save 事件</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>宿主保存报表定义 JSON（数据库、文件，由宿主决定）</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>业务页面取出报表定义，交给 &lt;xh-report-viewer&gt;</span></span>
<span class="line"><span>  │  dataProvider(request)：查看器按报表定义算出取数请求</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>宿主取数（直接查库、调接口，或在服务端聚合）</span></span>
<span class="line"><span>  │  交回明细行或汇总行</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>查看器计算并绘出视图 ──▶ 联动、下钻事件 ──▶ export(&#39;xlsx&#39;)</span></span></code></pre></div><ol><li>设计：在设计器里编辑报表，设计器派发 <code>schema-change</code> 与 <code>save</code>，宿主把报表定义存起来。</li><li>取数：查看器按报表定义、参数取值与联动选中，为每个数据集算出取数请求，交给宿主的取数回调。</li><li>计算与显示：取回的数据在浏览器里计算成明细表、分组报表、交叉表或看板的各张卡片，再绘出来；参数或联动变了，只重算受影响的部分。</li></ol><h2 id="运行环境" tabindex="-1">运行环境 <a class="header-anchor" href="#运行环境" aria-label="Permalink to “运行环境”">​</a></h2><ul><li><code>@xihan-report/core</code> 不依赖 DOM，可以在浏览器、Node.js 或其它 JavaScript 运行环境里校验报表、生成取数请求并计算结果。</li><li><code>@xihan-report/runtime</code> 与 <code>@xihan-report/designer</code> 要在支持 Custom Elements 的浏览器里运行。</li><li>计算字段与公式度量要一个表达式引擎，用 <code>@xihan-ui/expression</code> 的 <code>createExpressionEngine()</code> 即可；报表里没有公式时不需要。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="./quickstart">快速开始</a>：在任意前端项目里装包，显示一张明细表。</li><li><a href="./guide/structure">报表结构</a>：数据集、参数与几种主体视图。</li></ul>`,16)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};